@Test public void testSetValue() {
    when(mockDatabaseReference.setValue(1)).thenReturn(mockTask);

    TestObserver sub = TestObserver.create();

    RxFirebaseDatabase.setValue(mockDatabaseReference, 1).subscribe(sub);

    verifyAddOnCompleteListenerForTask();
    callTaskOnComplete();

    sub.assertComplete();
    sub.assertNoErrors();
    sub.dispose();
  }

